// Normaliza o evento messages.upsert da Evolution API
const corpo = $input.first().json.body ?? {}
const dados = corpo.data ?? {}
const chave = dados.key ?? {}
const jid = chave.remoteJid ?? ''
const mensagem = dados.message ?? {}
const texto = (mensagem.conversation ?? mensagem.extendedTextMessage?.text ?? '').trim()

// motivo = null quando a mensagem deve ser respondida pela LLM
let motivo = null
if (corpo.event !== 'messages.upsert') motivo = 'evento'
else if (chave.fromMe) motivo = 'propria'
else if (!jid.endsWith('@s.whatsapp.net') && !jid.endsWith('@lid')) motivo = 'grupo'
else if (!texto) motivo = 'midia'

// Em contas com LID, o remoteJid não é o número: ele vem em remoteJidAlt (ou senderPn)
const jidTelefone = [jid, chave.remoteJidAlt, chave.senderPn].find((j) => j?.endsWith('@s.whatsapp.net'))
const numero = (jidTelefone ?? jid).split('@')[0]

return [{
  json: {
    motivo,
    instancia: corpo.instance,
    jid: jidTelefone ?? jid,
    telefone: numero,
    mensagemId: chave.id,
    texto,
    nomeWhatsApp: dados.pushName ?? null,
  },
}]

// Monta a requisição para o Ollama: instruções + histórico da conversa.
// O campo format restringe a resposta ao JSON { acao, dados }.
const estado = $input.first().json

const FORMATO = {
  type: 'object',
  properties: {
    acao: {
      type: 'string',
      enum: ['MENSAGEM', 'CARDAPIO', 'RESUMIR_PEDIDO', 'CONFIRMAR_PEDIDO', 'CONSULTAR_PEDIDO'],
    },
    dados: {
      type: 'object',
      properties: {
        texto: { type: 'string' },
        itens: {
          type: 'array',
          items: {
            type: 'object',
            properties: { produtoId: { type: 'integer' }, quantidade: { type: 'integer' } },
            required: ['produtoId', 'quantidade'],
          },
        },
        endereco: { type: 'string' },
        cep: { type: 'string' },
        pagamento: { type: 'string', enum: ['dinheiro', 'pix', 'cartao'] },
        pedidoId: { type: 'integer' },
      },
    },
  },
  required: ['acao', 'dados'],
}

const real = (valor) => `R$ ${Number(valor).toFixed(2).replace('.', ',')}`
const pendente = estado.pedidoPendente
  ? estado.pedidoPendente.itens.map((i) => `${i.quantidade}x ${i.nome}`).join(', ') +
    ` (total ${real(estado.pedidoPendente.total)})`
  : 'nenhum'

const instrucoes = `Você é o atendente virtual do restaurante ${estado.restauranteNome} no WhatsApp. Atenda os clientes em português do Brasil, com mensagens curtas, simpáticas e informais.

Você não fala direto com o cliente: cada resposta sua é um JSON com UMA ação, que o sistema executa. Responda sempre no formato {"acao": "...", "dados": {...}}.

AÇÕES
- MENSAGEM: envia dados.texto ao cliente pelo WhatsApp e encerra a sua vez. Use para responder, perguntar ou pedir confirmação.
  Exemplo: {"acao": "MENSAGEM", "dados": {"texto": "Oi! Quer ver o cardápio?"}}
- CARDAPIO: consulta os produtos e preços atuais.
  Exemplo: {"acao": "CARDAPIO", "dados": {}}
- RESUMIR_PEDIDO: monta o pedido e calcula o total. Precisa dos itens (produtoId do cardápio e quantidade), endereço, CEP e forma de pagamento (dinheiro, pix ou cartao, sempre paga na entrega). Depois mostre o resumo ao cliente com MENSAGEM e pergunte se pode confirmar.
  Exemplo: {"acao": "RESUMIR_PEDIDO", "dados": {"itens": [{"produtoId": 1, "quantidade": 2}], "endereco": "Rua das Flores, 10", "cep": "12345-000", "pagamento": "pix"}}
- CONFIRMAR_PEDIDO: cria o pedido que foi resumido. Só use depois que o cliente disser que confirma o resumo.
  Exemplo: {"acao": "CONFIRMAR_PEDIDO", "dados": {}}
- CONSULTAR_PEDIDO: consulta o status de um pedido do cliente. dados.pedidoId é opcional; sem ele, consulta o último pedido.
  Exemplo: {"acao": "CONSULTAR_PEDIDO", "dados": {}}

O resultado de cada ação volta para você numa mensagem que começa com "--- RESULTADO <AÇÃO> ---". Essas mensagens vêm do sistema, não do cliente: o cliente não as vê.

REGRAS
- Você NÃO sabe o que o restaurante vende até usar CARDAPIO. Se o cliente perguntar o que tem, pedir o cardápio, perguntar preço ou quiser fazer um pedido, use CARDAPIO primeiro e só então responda com MENSAGEM, citando os itens e preços exatamente como vieram.
- Nunca invente produtos, preços, prazos ou status. Repasse o status do pedido exatamente como veio.
- Não presuma dados que o cliente não informou (como a forma de pagamento): pergunte.
- Use apenas produtoId que apareceram no cardápio.
- Se faltar alguma informação do pedido, pergunte ao cliente com MENSAGEM.
- Se uma ação devolver erro, corrija e tente de novo, ou explique o problema ao cliente.
- Para assuntos que não sejam do restaurante, diga com educação que só pode ajudar com pedidos.

CONTEXTO
- Agora: ${$now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy HH:mm')}
- Nome do cliente: ${estado.nomeCliente ?? 'desconhecido'}
- Pedido aguardando confirmação: ${pendente}
- Último pedido: ${estado.ultimoPedidoId ? '#' + estado.ultimoPedidoId : 'nenhum'}`

return [{
  json: {
    ...estado,
    requisicao: {
      model: $env.OLLAMA_MODEL,
      stream: false,
      think: false,
      format: FORMATO,
      options: { temperature: 0.3 },
      messages: [{ role: 'system', content: instrucoes }, ...estado.historico],
    },
  },
}]

// Lê a ação escolhida pela LLM e decide o próximo passo do orquestrador
const LIMITE_PASSOS = 6
const DESCULPA = 'Desculpe, tive um problema aqui. Pode repetir, por favor?'

const estado = { ...$('Preparar chamada').first().json }
delete estado.requisicao
estado.passo += 1

let resposta = null
try {
  resposta = JSON.parse($input.first().json.message?.content ?? '')
} catch (erro) {
  resposta = null
}

const valida = resposta && typeof resposta.acao === 'string' && typeof resposta.dados === 'object' &&
  (resposta.acao !== 'MENSAGEM' || (resposta.dados.texto ?? '').trim() !== '')

if (!valida) {
  estado.falhas += 1
  if (estado.falhas > 1 || estado.passo >= LIMITE_PASSOS) {
    return [{ json: { ...estado, acao: 'MENSAGEM', dados: { texto: DESCULPA } } }]
  }
  estado.historico.push({
    role: 'user',
    content: '--- ERRO ---\nResposta inválida. Responda apenas com o JSON {"acao": "...", "dados": {...}}.',
  })
  return [{ json: { ...estado, acao: 'REPETIR', dados: {} } }]
}

estado.historico.push({ role: 'assistant', content: JSON.stringify(resposta) })

// Limite de passos: encerra a vez com uma mensagem em vez de seguir chamando ações
if (estado.passo >= LIMITE_PASSOS && resposta.acao !== 'MENSAGEM') {
  return [{ json: { ...estado, acao: 'MENSAGEM', dados: { texto: DESCULPA } } }]
}

return [{ json: { ...estado, acao: resposta.acao, dados: resposta.dados } }]

// Devolve o resultado da ação para a LLM como uma mensagem do sistema
const estado = { ...$input.first().json }
estado.historico = [
  ...estado.historico,
  { role: 'user', content: `--- RESULTADO ${estado.acao} ---\n${estado.resultado}` },
]
delete estado.resultado
delete estado.acao
delete estado.dados
return [{ json: estado }]

// Valida o pedido proposto pela LLM e calcula o total com os preços do banco
const estado = { ...$('Interpretar ação').first().json }
const { itens = [], endereco = '', cep = '', pagamento = '' } = estado.dados
const produtos = new Map($input.all().map((item) => item.json).filter((p) => p.id).map((p) => [p.id, p]))
const real = (valor) => `R$ ${Number(valor).toFixed(2).replace('.', ',')}`

const erros = []
const quantidades = new Map()
for (const item of itens) {
  const id = Number(item.produtoId)
  const quantidade = Number(item.quantidade)
  if (!produtos.has(id)) erros.push(`produtoId ${item.produtoId} não existe no cardápio`)
  else if (!Number.isInteger(quantidade) || quantidade < 1) erros.push(`quantidade inválida para o produtoId ${id}`)
  else quantidades.set(id, (quantidades.get(id) ?? 0) + quantidade)
}
if (itens.length === 0) erros.push('nenhum item informado')
if (!endereco.trim()) erros.push('endereço não informado')
if (cep.replace(/\D/g, '').length !== 8) erros.push('CEP inválido (precisa ter 8 dígitos)')
if (!['dinheiro', 'pix', 'cartao'].includes(pagamento)) erros.push('forma de pagamento deve ser dinheiro, pix ou cartao')

if (erros.length) {
  return [{ json: { ...estado, resultado: `Erro: não foi possível montar o pedido: ${erros.join('; ')}.` } }]
}

const linhas = [...quantidades].map(([id, quantidade]) => ({
  produtoId: id,
  nome: produtos.get(id).nome,
  quantidade,
  precoUnitario: Number(produtos.get(id).preco),
}))
const total = linhas.reduce((soma, l) => soma + l.precoUnitario * l.quantidade, 0)

// confirmavel vira true quando o cliente responder (ver "Montar contexto")
estado.pedidoPendente = { itens: linhas, endereco: endereco.trim(), cep, pagamento, total, confirmavel: false }

const resultado = [
  'Pedido montado (ainda NÃO confirmado):',
  ...linhas.map((l) => `- ${l.quantidade}x ${l.nome} (${real(l.precoUnitario)} cada)`),
  `Total: ${real(total)}`,
  `Entrega: ${endereco.trim()}, CEP ${cep}`,
  `Pagamento na entrega: ${pagamento}`,
  'Mostre este resumo ao cliente com MENSAGEM e pergunte se pode confirmar.',
].join('\n')

return [{ json: { ...estado, resultado } }]

const estado = { ...$('Interpretar ação').first().json }
const pendente = estado.pedidoPendente

let erro = null
if (!pendente) erro = 'Erro: não há pedido montado. Use RESUMIR_PEDIDO antes.'
else if (!pendente.confirmavel) {
  erro = 'Erro: o cliente ainda não viu o resumo. Mostre o resumo com MENSAGEM e espere ele confirmar.'
}

if (erro) return [{ json: { ...estado, ok: false, resultado: erro } }]

return [{
  json: {
    ...estado,
    ok: true,
    corpoPedido: {
      nomeCliente: estado.nomeCliente,
      preco: pendente.total,
      metodoPagamento: pendente.pagamento,
      app: 'whatsapp',
      enderecoDestino: pendente.endereco,
      cepDestino: pendente.cep,
      itens: pendente.itens.map((i) => ({ produtoId: i.produtoId, quantidade: i.quantidade })),
    },
  },
}]

const estado = { ...$('Validar confirmação').first().json }
const pedido = $input.first().json
delete estado.ok
delete estado.corpoPedido

if (!pedido.id) {
  const detalhe = pedido.error?.message ?? pedido.error ?? 'erro desconhecido'
  return [{ json: { ...estado, resultado: `Erro ao criar o pedido: ${detalhe}. Peça desculpas ao cliente.` } }]
}

estado.clienteId = pedido.clienteId ?? estado.clienteId
estado.ultimoPedidoId = pedido.id
estado.pedidoPendente = null

return [{
  json: {
    ...estado,
    resultado: `Pedido #${pedido.id} criado com sucesso e recebido pelo restaurante. Avise o cliente com o número do pedido.`,
  },
}]

const estado = $('Interpretar ação').first().json
const pedidos = $input.all().map((item) => item.json).filter((p) => p.id)
const real = (valor) => `R$ ${Number(valor).toFixed(2).replace('.', ',')}`
const STATUS = {
  novo: 'recebido, aguardando o restaurante começar o preparo',
  em_preparo: 'em preparo',
  pronto: 'pronto, aguardando o entregador',
  saiu_para_entrega: 'saiu para entrega',
  entregue: 'entregue',
  cancelado: 'cancelado',
}

const pedidoId = estado.dados.pedidoId ?? estado.ultimoPedidoId
const pedido = pedidoId ? pedidos.find((p) => p.id === Number(pedidoId)) : pedidos[0]

let resultado
if (!pedidos.length) resultado = 'Este cliente ainda não tem pedidos.'
else if (!pedido) resultado = `Erro: o pedido #${pedidoId} não existe ou não é deste cliente.`
else {
  const itens = pedido.itens.map((i) => `${i.quantidade}x ${i.produto?.nome ?? 'item'}`).join(', ')
  const feitoEm = DateTime.fromISO(pedido.criadoEm).setZone('America/Sao_Paulo').toFormat('dd/MM HH:mm')
  resultado = `Pedido #${pedido.id} (feito em ${feitoEm}): ${STATUS[pedido.status] ?? pedido.status}. Itens: ${itens}. Total: ${real(pedido.preco)}.`
}

return [{ json: { ...estado, resultado } }]
